import numpy as np
X = np.random.default_rng(0).normal(size=(256, 64))

def last_layer_std(scale, layers=8, width=64):
    r = np.random.default_rng(1)
    A = X
    for _ in range(layers):
        A = np.maximum(0, A @ (r.normal(size=(width, width)) * scale))
    return A.std()

